import logging
from ute_ue.lteuepool import CfgFileBasedUePool


CONSTRUCTOR_PARAMETERS = 'CONSTRUCTOR_PARAMETERS'


class PrismaUePool(CfgFileBasedUePool):
    """Prisma Ue Pool"""

    def __init__(self, config_file_path=None, inline_config=None):
        """Basic initialization."""
        if inline_config is None:
            inline_config = {}
        super(PrismaUePool, self).__init__(config_file_path, inline_config)
        self.logger = logging.getLogger('ute_ue')

    def shutdown(self):
        self.logger.debug("Shutdown Prisma ue pool in taken devices:{}".format(self._taken_devices))
        for ue_name in list(self._taken_devices):
            self._return_device_to_available_devices(ue_name)

    def _return_device_to_available_devices(self, ue_name):
        ue = self._taken_devices[ue_name]
        ue.shutdown()
        super(PrismaUePool, self)._return_device_to_available_devices(ue_name)
